@app.route('/')
def home():
    return send_from_directory('.', 'index.html')

@app.route("/api/gadanie", methods=["POST"])
def gadanie():
    data = request.get_json()
    spread_type = data.get("spreadType")
    topic = data.get("topic")  # milosc, przyszlosc, kariera

    spread_definitions = {
        "Klasyczny": {
            "count": 3,
            "fields": lambda t: [t] * 3  # trzy identyczne opisy tematyczne
        },
        "Przeszłość–Teraźniejszość–Przyszłość": {
            "count": 3,
            "fields": ["przeszlosc", "terazniejszosc", "przyszlosc"]
        },
        "Miłość–Wyzwanie–Rada": {
            "count": 3,
            "fields": ["milosc", "wyzwanie", "rada"]
        },
        "Duchowe przesłanie": {
            "count": 1,
            "fields": ["przeslanie"]
        },
        "Droga 5 kart": {
            "count": 5,
            "fields": ["poczatek", "wyzwanie", "wewnetrzna sila", "rada", "rezultat"]
        }
    }

    if spread_type not in spread_definitions:
        return jsonify({"error": "Nieprawidłowy rodzaj rozkładu"}), 400

    spread_info = spread_definitions[spread_type]

    if spread_type == "Klasyczny":
        if topic not in ["milosc", "kariera", "przyszlosc"]:
            return jsonify({"error": "Nieprawidłowy temat dla rozkładu klasycznego"}), 400
        fields = spread_info["fields"](topic)
    else:
        fields = spread_info["fields"]

    
    shuffled_cards = random.sample(cards, len(cards))
    result = []

    for i in range(spread_info["count"]):
        card = shuffled_cards[i]
        field = fields[i]
        result.append({
            "name": card["name"],
            "description": card.get(field, "Brak opisu"),
            "image": f"/images/{card['image']}",
            "label": field.capitalize()  
        })

    return jsonify(result)

if __name__ == "__main__":
    app.run(debug=True)
